class Resequencer(private val next: SendChannel<Msg>) {
    private val window = PriorityQueue<Pair<Long, Msg>>(compareBy { it.first })
    private val mutex = Mutex()
    private var expected = 1L
    suspend fun accept(seq: Long, msg: Msg) = mutex.withLock {
        window += seq to msg                    // duplicates policy: keep last
        while (window.isNotEmpty() && window.peek().first == expected) {
            val (s, m) = window.poll()
            expected = s + 1
            next.send(m)                        // channel keeps delivery order
        }
    }
}
